#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

long long collect(vector<vector<long long>>& g, int r, int c, int row, int col) {
    long long gold = g[row][col];
    g[row][col] = 0;
    long long best = 0;
    int dr[4] = {1, -1, 0, 0};
    int dc[4] = {0, 0, 1, -1};
    for (int d = 0; d < 4; d++) {
        int nr = row + dr[d], nc = col + dc[d];
        if (nr >= 0 && nr < r && nc >= 0 && nc < c && g[nr][nc] > 0) best = max(best, collect(g, r, c, nr, nc));
    }
    g[row][col] = gold;
    return gold + best;
}

int main() {
    long long r;
    long long c;
    cin >> r >> c;
    vector<vector<long long>> g(r, vector<long long>(c));
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            cin >> g[i][j];
        }
    }

    long long answer = 0;
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            if (g[i][j] > 0) answer = max(answer, collect(g, (int)r, (int)c, i, j));
        }
    }
    cout << answer << "\n";

    return 0;
}

