import java.util.*;

public class Main {
    static long collect(long[][] g, int r, int c, int row, int col) {
        long gold = g[row][col];
        g[row][col] = 0;
        long best = 0;
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};
        for (int d = 0; d < 4; d++) {
            int nr = row + dr[d], nc = col + dc[d];
            if (nr >= 0 && nr < r && nc >= 0 && nc < c && g[nr][nc] > 0) best = Math.max(best, collect(g, r, c, nr, nc));
        }
        g[row][col] = gold;
        return gold + best;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long r = sc.nextLong();
        long c = sc.nextLong();
        long[][] g = new long[(int) r][(int) c];
        for (int i = 0; i < g.length; i++) {
            for (int j = 0; j < g[i].length; j++) {
                g[i][j] = sc.nextLong();
            }
        }

        long answer = 0;
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (g[i][j] > 0) answer = Math.max(answer, collect(g, (int) r, (int) c, i, j));
            }
        }
        System.out.println(answer);
    }
}
